public class Solution {
    public TreeNode flipTree(TreeNode root, int val, int depth) {
        if (depth == 1) {
            root.val = val;
            return root;
        }

        if (root == null) {
            return null;
        }

        root.left = flipTree(root.left, val, depth - 1);
        root.right = flipTree(root.right, val, depth - 1);

        return root;
