public class Solution {
    public List<Integer> minMoves(int[] nums, int k) {
        int n = nums.length;
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }
        int res = Integer.MAX_VALUE;
        List<Integer> result = new ArrayList<>();
