import heapq

def second_minimum(n: int, edges: List[List[int]], time: int, change: int) -> int:
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    dist = [-1] * (n + 1)
    queue = [(0, 1)]
    dist[1] = 0

    while queue:
        t1, v1 = heapq.heappop(queue)

        if v1 == n:
            return t1

        for v2 in adj[v1]:
            t2 = t1 + time
            waiting = change - (t2 % change) if (t2 // change) % 2 == 1 else 0

            if dist[v2] == -1 or dist[v2] > t2 + waiting:
                if dist[v2] != -1:
                    heapq.heappush(queue, (dist[v2], v2))
                dist[v2] = t2 + waiting
                heapq.heappush(queue, (dist[v2], v2))

    return -1

def second_minimum_modified(amount: List[int]) -> int:
    return second_minimum(len(amount), [[i, i+1] for i in range(len(amount)-1)], 1, 1)
