def ladderLength(beginWord, endWord, wordList):
    if endWord not in wordList:
        return 0

    q = deque([beginWord])
    visited = set([beginWord])
    depth = 1

    while q:
        levelSize = len(q)
        for _ in range(levelSize):
            current = q.popleft()
            if current == endWord:
                return depth

            for word in wordList:
                if word not in visited:
                    diff = sum(1 for j in range(len(current)) if current[j] != word[j])
                    if diff == 1:
                        q.append(word)
                        visited.add(word)
        depth += 1
    return 0
