private void backtrack(String num, int target, int index, long prev, long curr, String path, List<String> result) {
    if (index == num.length()) {
        if (curr == target) {
            result.add(path);
        }
        return;
    }
    for (int i = index; i < num.length(); i++) {
        if (i > index && num.charAt(index) == '0') break;
        long val = Long.parseLong(num.substring(index, i + 1));
        if (index == 0) {
            backtrack(num, target, i + 1, val, val, path + val, result);
        } else {
            backtrack(num, target, i + 1, val, curr + val, path + "+" + val, result);
            backtrack(num, target, i + 1, -val, curr - val, path + "-" + val, result);
            backtrack(num, target, i + 1, prev * val, (curr - prev) + (prev * val), path + "*" + val, result);
