public int longestConsecutive(TreeNode root) {
    if (root == null) {
        return 0;
    }

    int longestSeq = 0;

    Queue<TreeNode> queue = new LinkedList<>();
    queue.offer(root);

    while (!queue.isEmpty()) {
        TreeNode node = queue.poll();

        if (node.left != null) {
            queue.offer(node.left);
        }

        if (node.right != null) {
            queue.offer(node.right);
        }

        int currentSeq = 1;
        int currentNum = node.val;

        while (node.left != null && node.left.val == currentNum + 1) {
            currentNum = node.left.val;
            currentSeq++;
            node = node.left;
        }

        while (node.right != null && node.right.val == currentNum + 1) {
            currentNum = node.right.val;
            currentSeq++;
            node = node.right;
