def rearrange_string(s, k):
    if k <= 1:
        return s

    char_count = {}
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    max_heap = []
    for char, count in char_count.items():
        max_heap.append((-count, char))
    max_heap.sort()

    result = []
    while max_heap:
        temp = []
        for _ in range(k):
            if not max_heap:
                return ""
            count, char = max_heap.pop(0)
            result.append(char)
            if count + 1 < 0:
                temp.append((count + 1, char))
        for item in temp:
            max_heap.append(item)
        max_heap.sort()

    return ''.join(result)
