public String findClosestAbbreviation(String target, List<String> dictionary) {
    List<String> abbreviations = generateAbbreviations(target);
    String closestAbbreviation = null;
    int minDistance = Integer.MAX_VALUE;
    for (String abbreviation : abbreviations) {
        for (String word : dictionary) {
            int distance = calculateDistance(abbreviation, word);
            if (distance < minDistance) {
                minDistance = distance;
                closestAbbreviation = abbreviation;
            }
        }
    }
    return closestAbbreviation;
}

private int calculateDistance(String a, String b) {
    int[][] dp = new int[a.length() + 1][b.length() + 1];
    for (int i = 0; i <= a.length(); i++) {
        for (int j = 0; j <= b.length(); j++) {
            if (i == 0) {
                dp[i][j] = j;
            } else if (j == 0) {
                dp[i][j] = i;
            } else if (a.charAt(i - 1) == b.charAt(j - 1)) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = 1 + Math.min(dp[i - 1][j - 1], Math.min(dp[i - 1][j], dp[i][j - 1]));
            }
        }
    }
    return dp[a.length()][b.length()];
}
