            if in_degree[next] == 0:
                q.append(next)

    return len(order) == numCourses

def sequenceReconstruction(nums, sequences):
    n = len(nums)
    adj_list = [[] for _ in range(n)]
    in_degree = [0] * n

    for seq in sequences:
        for i in range(len(seq) - 1):
            u, v = seq[i], seq[i + 1]
            adj_list[u].append(v)
            in_degree[v] += 1

    q = deque([i for i in range(n) if in_degree[i] == 0])
    order = []

    while q:
        if len(q) > 1:
            return False
        curr = q.popleft()
        order.append(curr)
