        while ((end - start) >> samePrefixBits) < 1:
            samePrefixBits -= 1
        range = 1 << samePrefixBits
        ans.append(f"{start >> 24}.{(start >> 16) & 255}.{(start >> 8) & 255}.{start & 255}/{32 - samePrefixBits}")
