    in_degree = [0] * numCourses
    adj_list = [[] for _ in range(numCourses)]

    for p in prerequisites:
        adj_list[p[1]].append(p[0])
        in_degree[p[0]] += 1

    q = deque([i for i in range(numCourses) if in_degree[i] == 0])
    order = []

