import java.util.ArrayList;
import java.util.List;

public class Solution {
    public List<List<Integer>> countArrangement(int n, int k) {
        List<List<Integer>> res = new ArrayList<>();
        boolean[] visited = new boolean[n+1];
        helper(n, 1, visited, new ArrayList<>(), res, k);
        return res;
    }

    void helper(int n, int idx, boolean[] visited, List<Integer> path, List<List<Integer>> res, int k) {
