        for(int i=1; i<=n; i++){
            if (!visited[i] && (idx % i == 0 || i % idx == 0)) {
                visited[i] = true;
                path.add(i);
                helper(n, idx+1, visited, path, res, k);
                path.remove(path.size()-1);
                visited[i] = false;
